22	pub fn rewrite(src: &str) -> String {
23	    let Ok(body) = parse::parse(src) else { return src.to_string() };
24	    let mut lines: Vec<String> = src.lines().map(String::from).collect();
25	    let mut changed = false;
26	    for s in &body {
27	        let St::Assign(ts, Ex::Call(f, args)) = &s.st else { continue };
28	        let ([Ex::Name(n)], Ex::Name(o)) = (ts.as_slice(), f.as_ref()) else { continue };
29	        if o != "object" || !args.is_empty() || !safe(&body, n) {
30	            continue;
31	        }
32	        let Some(new) = replace(&lines, s.line, n) else { continue };
33	        lines = new;
34	        changed = true;
35	    }
36	    if !changed {
37	        return src.to_string();
38	    }
39	    let mut out = lines.join("\n");
40	    if src.ends_with('\n') {
41	        out.push('\n');
42	    }
43	    out
44	}
