46	// Every statement, nested blocks and function bodies included.
47	fn each_stmt(body: &[Stmt], f: &mut dyn FnMut(&Stmt)) {
48	    for s in body {
49	        f(s);
50	        each_block(&s.st, &mut |b| each_stmt(b, f));
51	    }
52	}
