64	// `x is None`, `x is not None`, `x == None`, `x != None`: (x, the op).
65	fn none_test(e: &Ex) -> Option<(&Ex, &'static str)> {
66	    let Ex::Cmp(l, ops) = e else { return None };
67	    let [(op, r)] = ops.as_slice() else { return None };
68	    if !matches!(*op, "is" | "is not" | "==" | "!=") {
69	        return None;
70	    }
71	    match (l.as_ref(), r) {
72	        (x, Ex::NoneV) | (Ex::NoneV, x) => Some((x, op)),
73	        _ => None,
74	    }
75	}
