77	// `x is N` (or `x is not N`, ==, !=): (x, the op).
78	fn sentinel_test<'a>(e: &'a Ex, n: &str) -> Option<(&'a Ex, &'static str)> {
79	    let Ex::Cmp(l, ops) = e else { return None };
80	    let [(op, r)] = ops.as_slice() else { return None };
81	    match (l.as_ref(), r) {
82	        (x, y) | (y, x) if is_name(y, n) && !is_name(x, n) => Some((x, op)),
83	        _ => None,
84	    }
85	}
