        St::If(arms, _) => arms.iter().all(|(c, _)| e(c)),
        St::While(c, _, _) => e(c),
        St::Raise(Some(x), _) => e(x),
        St::With(items, _) => items.iter().all(|(x, _)| e(x)),
        St::Del(xs) => xs.iter().all(e),
        _ => true,
    }
