                    return false;
                }
            }
            St::For(t, _, b, els) => {
                let mut inner = pre.clone();
                names_in(t, &mut inner);
                if !block_ok(b, n, carriers, &inner) || els.as_ref().is_some_and(|x| !block_ok(x, n, carriers, &pre)) {
