import re
import sys

INT_RE = re.compile(r'^[-+]?\d+$')

def main():
    store = {}
    txns = []

    def record(key):
        if txns:
            log = txns[-1]
            if key not in log:
                log[key] = store.get(key, 'X')

    def set_key(key, value):
        record(key)
        store[key] = value

    out = []
    for raw in ['SET a 1', 'GET a']:
        line = raw.strip()
        parts = line.split()
        cmd = parts[0]
        args = parts[1:]
        if cmd == 'SET':
            set_key(args[0], args[1])
        elif cmd == 'GET':
            out.append(store.get(args[0], 'NULL'))
    print('\n'.join(out))

main()

